  assert.ok(t.inputSchema);
  assert.equal(t.inputSchema.additionalProperties, false);
  assert.ok(t.inputSchema.properties.cursor);
  assert.equal(t.inputSchema.properties.cursor.type, 'string');
  assert.ok(t.inputSchema.properties.page_size);
  assert.equal(t.inputSchema.properties.page_size.type, 'integer');
  assert.equal(t.inputSchema.properties.page_size.minimum, 1);
  assert.equal(t.inputSchema.properties.page_size.maximum, 3);
});

// --- First page (default page_size=2, no cursor) ---
test('first page returns first 2 events and next_cursor', async () => {
  const r = await callTool('events_list', {});
  const data = JSON.parse(r.content[0].text);
  assert.equal(data.events.length, 2);
  assert.equal(data.events[0].id, 'e1');
  assert.equal(data.events[1].id, 'e2');
  assert.ok(data.next_cursor);
  assert.equal(typeof data.next_cursor, 'string');
});

// --- Second page with cursor ---
test('second page returns remaining events', async () => {
  const r1 = await callTool('events_list', {});
  const data1 = JSON.parse(r1.content[0].text);
  const cursor = data1.next_cursor;

  const r2 = await callTool('events_list', { cursor });
  const data2 = JSON.parse(r2.content[0].text);
  assert.equal(data2.events.length, 2);
  assert.equal(data2.events[0].id, 'e3');
  assert.equal(data2.events[1].id, 'e4');
  assert.equal(data2.next_cursor, undefined);
});

// --- page_size=1 ---
test('page_size=1 returns one event per page', async () => {
  const r = await callTool('events_list', { page_size: 1 });
  const data = JSON.parse(r.content[0].text);
  assert.equal(data.events.length, 1);
  assert.equal(data.events[0].id, 'e1');
  assert.ok(data.next_cursor);
});

// --- page_size=3 ---
test('page_size=3 returns up to 3 events', async () => {
  const r = await callTool('events_list', { page_size: 3 });
  const data = JSON.parse(r.content[0].text);
  assert.equal(data.events.length, 3);
  assert.equal(data.events[0].id, 'e1');
  assert.equal(data.events[2].id, 'e3');
  assert.ok(data.next_cursor);
});

// --- Last page: no next_cursor ---
test('last page has no next_cursor', async () => {
  // Get cursor pointing to last event
  const r1 = await callTool('events_list', { page_size: 3 });
  const data1 = JSON.parse(r1.content[0].text);
  const r2 = await callTool('events_list', { cursor: data1.next_cursor });
  const data2 = JSON.parse(r2.content[0].text);
  assert.equal(data2.events.length, 1);
  assert.equal(data2.events[0].id, 'e4');
  assert.equal(data2.next_cursor, undefined);
});

