  await assert.rejects(
    () => callTool('events_list', { page_size: 0 }),
    /page_size must be an integer between 1 and 3/
  );
});

// --- Invalid page_size: 4 ---
test('rejects page_size=4', async () => {
  await assert.rejects(
    () => callTool('events_list', { page_size: 4 }),
    /page_size must be an integer between 1 and 3/
  );
});

