test('rejects non-integer page_size', async () => {
  await assert.rejects(
    () => callTool('events_list', { page_size: 2.5 }),
    /page_size must be an integer between 1 and 3/
  );
});

// --- Invalid page_size: string ---
test('rejects string page_size', async () => {
  await assert.rejects(
    () => callTool('events_list', { page_size: '2' }),
    /page_size must be an integer between 1 and 3/
  );
});

// --- Invalid cursor (garbage) ---
test('rejects garbage cursor', async () => {
  await assert.rejects(
    () => callTool('events_list', { cursor: 'not-a-valid-cursor' }),
    /Invalid cursor/
  );
});

// --- Invalid cursor (wrong type) ---
test('rejects non-string cursor', async () => {
  await assert.rejects(
    () => callTool('events_list', { cursor: 123 }),
    /cursor must be a string/
  );
});

// --- Extra fields ---
test('rejects extra fields', async () => {
  await assert.rejects(
    () => callTool('events_list', { extra: 'field' }),
    /Unexpected field: extra/
  );
});

// --- Unknown tool ---
test('rejects unknown tool', async () => {
  await assert.rejects(
    () => callTool('unknown_tool', {}),
    /Unknown tool: unknown_tool/
  );
});

// --- Full pagination walkthrough ---
test('full walkthrough: page through all events', async () => {
  const allIds = [];
  let cursor = undefined;
  while (true) {
    const args = {};
    if (cursor) args.cursor = cursor;
    const r = await callTool('events_list', args);
    const data = JSON.parse(r.content[0].text);
    for (const e of data.events) allIds.push(e.id);
    if (!data.next_cursor) break;
    cursor = data.next_cursor;
  }
  assert.deepEqual(allIds, ['e1', 'e2', 'e3', 'e4']);
});
